#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as dt
import importlib.util
import os
import py_compile
import shutil
import subprocess
import sys
from pathlib import Path

VERSION="0.7.0"
MODIFIED_B64={'frontend/tools/generate_llm_context_map.py': {'old': '', 'new': ''}}
CREATED_B64={'frontend/docs/llm_context/updates/v0700_computer_vision_frame.md': '', 'frontend/src/Pages/ComputerVisionPage.tsx': '', 'frontend/src/api/visionAppApi.ts': '', 'frontend/src/components/ComputerVision/VisionViewport.tsx': '', 'frontend/src/components/ComputerVision/WorkingModulePanel.tsx': '', 'frontend/src/components/ComputerVision/ComputerVision.css': '', 'frontend/src/components/ComputerVision/MasterSamplePanel.tsx': '', 'frontend/src/components/ComputerVision/IotModulePanel.tsx': '', 'backend/tests/vision_app/test_vision_app_frame_v0100.py': '', 'backend/app/api/v1/endpoints/vision_app_api.py': '', 'backend/app/services/vision_app/repository.py': '', 'backend/app/services/vision_app/models.py': '', 'backend/app/services/vision_app/roi_search.py': '', 'backend/app/services/vision_app/__init__.py': 'ZnJvbSAubW9kZWxzIGltcG9ydCBWaXNpb25Qcm9ncmFtRGVmaW5pdGlvbgoKX19hbGxfXyA9IFsiVmlzaW9uUHJvZ3JhbURlZmluaXRpb24iXQo=', 'backend/app/services/vision_app/runtime.py': '', 'backend/app/services/vision_app/io_runtime.py': ''}
MODIFIED={p:{k:base64.b64decode(v).decode('utf-8') for k,v in x.items()} for p,x in MODIFIED_B64.items()}
CREATED={p:base64.b64decode(v).decode('utf-8') for p,v in CREATED_B64.items()}


def resolve_roots(frontend_arg=None, backend_arg=None):
    cwd=Path.cwd().resolve();fe=[];be=[]
    if frontend_arg: fe.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg: be.append(Path(backend_arg).expanduser().resolve())
    fe += [cwd,cwd/'LambdaVisionSuper',cwd.parent/'LambdaVisionSuper']
    be += [cwd,cwd/'LambdaVisionSuperBackEnd',cwd.parent/'LambdaVisionSuperBackEnd']
    frontend=next((p for p in fe if (p/'src/App.tsx').exists() and (p/'src/Pages/MainScreen.tsx').exists()),None)
    backend=next((p for p in be if (p/'app/main.py').exists() and (p/'app/api/v1/api.py').exists()),None)
    if frontend is None: raise RuntimeError('Cannot locate LambdaVisionSuper frontend; use --frontend')
    if backend is None: raise RuntimeError('Cannot locate LambdaVisionSuperBackEnd; use --backend')
    return frontend,backend


def real_path(fe,be,virtual):
    if virtual.startswith('frontend/'): return fe/virtual[len('frontend/'):]
    if virtual.startswith('backend/'): return be/virtual[len('backend/'):]
    raise ValueError(virtual)


def modified_state(path,old,new):
    if not path.exists(): return 'MISSING'
    cur=path.read_text(encoding='utf-8')
    if cur==new:return 'OK'
    if cur==old:return 'UPDATE'
    return 'CONFLICT'


def created_state(path,desired):
    if not path.exists():return 'CREATE'
    return 'OK' if path.read_text(encoding='utf-8')==desired else 'CONFLICT'


def route_states(fe,be):
    app=(fe/'src/App.tsx').read_text(encoding='utf-8')
    main=(fe/'src/Pages/MainScreen.tsx').read_text(encoding='utf-8')
    api=(be/'app/api/v1/api.py').read_text(encoding='utf-8')
    app_state='OK' if '/computer-vision' in app and 'ComputerVisionPage' in app else ('PATCH' if '<Route' in app and 'MainScreen' in app else 'CONFLICT')
    main_state='OK' if "label: 'Computer Vision'" in main else ('PATCH' if "label: 'App Builder'" in main and 'homeActions' in main else 'CONFLICT')
    api_state='OK' if 'vision_app_api' in api and 'prefix="/computer-vision"' in api else ('PATCH' if 'api_router.include_router' in api else 'CONFLICT')
    return app_state,main_state,api_state


def scan(fe,be):
    print('='*100);print('COMPUTER VISION FRAME V0.7.0 — I/O + MASTER SAMPLE + WORKING STATIONS');print('='*100)
    print('Frontend :',fe);print('Backend  :',be);print()
    conflicts=0
    for virtual,payload in MODIFIED.items():
        state=modified_state(real_path(fe,be,virtual),payload['old'],payload['new']);print(f'  [{state:10}] {virtual}');conflicts += state in {'MISSING','CONFLICT'}
    for virtual,desired in CREATED.items():
        state=created_state(real_path(fe,be,virtual),desired);print(f'  [{state:10}] {virtual}');conflicts += state=='CONFLICT'
    app,main,api=route_states(fe,be)
    print(f'  [{app:10}] frontend/src/App.tsx');print(f'  [{main:10}] frontend/src/Pages/MainScreen.tsx');print(f'  [{api:10}] backend/app/api/v1/api.py')
    conflicts += sum(s=='CONFLICT' for s in (app,main,api))
    req=be/'requirements.txt';req_state='OK' if req.exists() and 'pymodbus' in req.read_text(encoding='utf-8').lower() else ('PATCH' if req.exists() else 'SKIP')
    print(f'  [{req_state:10}] backend/requirements.txt (pymodbus)')
    print('\nFrame contract:')
    print('  Main Screen -> Computer Vision')
    print('  IOT: Modbus trigger input + OK/NG output pulse')
    print('  Master Sample: stored image + many ROI/stations + Manual / Blur Template / Fourier Phase localization')
    print('  Working: Global whole-image Lab Services + Local per-station Lab Services + basic OK/NG rule frame')
    print('  Internal service calls use LabServiceRuntime directly; LAB internals remain frozen')
    print('  Context generator + v0.7 handoff MD included')
    if conflicts: print(f'\n[WARN] {conflicts} conflict/base issue(s); apply will stop safely.')
    return 0


def preflight(fe,be):
    errors=[]
    for virtual,payload in MODIFIED.items():
        s=modified_state(real_path(fe,be,virtual),payload['old'],payload['new'])
        if s not in {'UPDATE','OK'}: errors.append(f'{virtual}: {s}')
    for virtual,desired in CREATED.items():
        s=created_state(real_path(fe,be,virtual),desired)
        if s not in {'CREATE','OK'}: errors.append(f'{virtual}: {s}')
    app,main,api=route_states(fe,be)
    for label,state in [('App.tsx',app),('MainScreen.tsx',main),('api.py',api)]:
        if state=='CONFLICT': errors.append(f'{label}: no safe patch anchor')
    if errors: raise RuntimeError('Safe update stopped:\n  - '+'\n  - '.join(errors))


def backup(fe,be,paths):
    root=fe/'.lambda_updater_backups'/f'computer_vision_v0700_{dt.datetime.now().strftime("%Y%m%d_%H%M%S")}'
    root.mkdir(parents=True,exist_ok=True)
    for p in paths:
        if not p.exists():continue
        try: rel=p.relative_to(fe);dst=root/'frontend'/rel
        except ValueError: rel=p.relative_to(be);dst=root/'backend'/rel
        dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dst)
    return root


def patch_app(fe):
    p=fe/'src/App.tsx';t=p.read_text(encoding='utf-8')
    if 'ComputerVisionPage' not in t:
        lines=t.splitlines();idx=next((i+1 for i,l in enumerate(lines) if "./Pages/MainScreen" in l and l.lstrip().startswith('import ')),None)
        if idx is None: idx=next((i+1 for i,l in enumerate(lines) if l.lstrip().startswith('import ')),None)
        if idx is None: raise RuntimeError('Cannot patch App.tsx ComputerVisionPage import')
        lines.insert(idx,"import { ComputerVisionPage } from './Pages/ComputerVisionPage';");t='\n'.join(lines)+('\n' if t.endswith('\n') else '')
    if '/computer-vision' not in t:
        lines=t.splitlines();idx=next((i for i,l in enumerate(lines) if 'path="/inspection"' in l),None)
        if idx is None: idx=next((i for i,l in enumerate(lines) if 'path="/labs"' in l),None)
        if idx is None: idx=next((i for i,l in enumerate(lines) if 'path="*"' in l),None)
        if idx is None: raise RuntimeError('Cannot patch App.tsx Computer Vision route')
        indent=lines[idx][:len(lines[idx])-len(lines[idx].lstrip())]
        lines.insert(idx+1 if 'path="*"' not in lines[idx] else idx,indent+'<Route path="/computer-vision" element={<ComputerVisionPage />} />');t='\n'.join(lines)+('\n' if t.endswith('\n') else '')
    p.write_text(t,encoding='utf-8')


def patch_main(fe):
    p=fe/'src/Pages/MainScreen.tsx';t=p.read_text(encoding='utf-8')
    if "label: 'Computer Vision'" in t:return
    if 'Network' not in t.split('\n',3)[0:3].__str__():
        import re
        m=re.search(r"import \{([^}]+)\} from 'lucide-react';",t)
        if m:
            names=m.group(1).strip()
            if 'Network' not in names: t=t[:m.start(1)]+names+', Network'+t[m.end(1):]
    lines=t.splitlines();idx=next((i for i,l in enumerate(lines) if "label: 'App Builder'" in l),None)
    if idx is None: raise RuntimeError('Cannot patch MainScreen: App Builder action anchor not found')
    indent=lines[idx][:len(lines[idx])-len(lines[idx].lstrip())]
    comma='' if lines[idx].rstrip().endswith(',') else ','
    if comma: lines[idx]=lines[idx]+comma
    lines.insert(idx+1,indent+"{ id: 'computer-vision', label: 'Computer Vision', icon: Network, activeColor: 'purple', onClick: () => navigate('/computer-vision') },")
    p.write_text('\n'.join(lines)+('\n' if t.endswith('\n') else ''),encoding='utf-8')


def patch_api(be):
    p=be/'app/api/v1/api.py';t=p.read_text(encoding='utf-8')
    lines=t.splitlines()
    if 'vision_app_api' not in t:
        idx=max((i for i,l in enumerate(lines) if l.startswith('from app.api.v1.endpoints import ')),default=-1)
        lines.insert(idx+1,'from app.api.v1.endpoints import vision_app_api')
    if 'prefix="/computer-vision"' not in '\n'.join(lines):
        idx=max((i for i,l in enumerate(lines) if 'api_router.include_router' in l),default=-1)
        if idx<0: raise RuntimeError('Cannot patch api.py: no include_router anchor')
        lines.insert(idx+1,'api_router.include_router(vision_app_api.router, prefix="/computer-vision", tags=["Computer Vision"])')
    p.write_text('\n'.join(lines)+('\n' if t.endswith('\n') else ''),encoding='utf-8')


def patch_requirements(be):
    p=be/'requirements.txt'
    if not p.exists(): return False
    t=p.read_text(encoding='utf-8')
    if 'pymodbus' in t.lower(): return False
    p.write_text(t.rstrip()+'\npymodbus>=3.0,<4.0\n',encoding='utf-8');return True


def regenerate(fe,be):
    g=fe/'tools/generate_llm_context_map.py'
    cmd=[sys.executable,str(g),'--frontend',str(fe),'--backend',str(be)]
    if '--output-dir' in g.read_text(encoding='utf-8'): cmd += ['--output-dir',str(fe/'docs/llm_context')]
    r=subprocess.run(cmd,cwd=str(fe),text=True,capture_output=True)
    if r.returncode!=0: raise RuntimeError('Context generator failed:\n'+(r.stdout+'\n'+r.stderr).strip())
    if r.stdout.strip(): print(r.stdout.strip())


def apply(fe,be):
    preflight(fe,be)
    targets=[real_path(fe,be,k) for k in list(MODIFIED)+list(CREATED)]+[fe/'src/App.tsx',fe/'src/Pages/MainScreen.tsx',be/'app/api/v1/api.py',be/'requirements.txt']
    root=backup(fe,be,targets)
    for virtual,payload in MODIFIED.items():
        p=real_path(fe,be,virtual)
        if p.read_text(encoding='utf-8')!=payload['new']:p.write_text(payload['new'],encoding='utf-8');print('[WRITE]',virtual)
    for virtual,desired in CREATED.items():
        p=real_path(fe,be,virtual);p.parent.mkdir(parents=True,exist_ok=True)
        if not p.exists() or p.read_text(encoding='utf-8')!=desired:p.write_text(desired,encoding='utf-8');print('[WRITE]',virtual)
    patch_app(fe);print('[PATCH] frontend/src/App.tsx')
    patch_main(fe);print('[PATCH] frontend/src/Pages/MainScreen.tsx')
    patch_api(be);print('[PATCH] backend/app/api/v1/api.py')
    if patch_requirements(be):print('[PATCH] backend/requirements.txt + pymodbus')
    regenerate(fe,be)
    print('[OK] Backup:',root);print('Run verify next.');return 0


def python_syntax(be):
    fails=[];count=0
    for virtual in CREATED:
        if virtual.startswith('backend/') and virtual.endswith('.py'):
            p=real_path(Path('/unused'),be,virtual);count+=1
            try:py_compile.compile(str(p),doraise=True)
            except Exception as e:fails.append(f'{p.relative_to(be)}: {e}')
    return count,fails


def ts_transpile(fe):
    files=[real_path(fe,Path('/unused'),v) for v in CREATED if v.startswith('frontend/') and v.endswith(('.ts','.tsx'))]
    code=r"""const fs=require("fs"),ts=require("typescript");let bad=false;for(const f of process.argv.slice(1)){const r=ts.transpileModule(fs.readFileSync(f,"utf8"),{fileName:f,reportDiagnostics:true,compilerOptions:{jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.ESNext}});const es=(r.diagnostics||[]).filter(x=>x.category===ts.DiagnosticCategory.Error);if(es.length){bad=true;console.error("TS_ERROR",f);for(const e of es)console.error(ts.flattenDiagnosticMessageText(e.messageText,"\n"));}}process.exit(bad?1:0);"""
    env=dict(os.environ);nr=subprocess.run(['npm','root','-g'],text=True,capture_output=True)
    if nr.returncode==0 and nr.stdout.strip():env['NODE_PATH']=nr.stdout.strip()+(os.pathsep+env['NODE_PATH'] if env.get('NODE_PATH') else '')
    return subprocess.run(['node','-e',code,*map(str,files)],cwd=str(fe),env=env,text=True,capture_output=True)


def verify(fe,be,skip_build=False):
    print('='*100);print('VERIFY COMPUTER VISION FRAME V0.7.0');print('='*100);fails=0
    app=(fe/'src/App.tsx').read_text(encoding='utf-8');main=(fe/'src/Pages/MainScreen.tsx').read_text(encoding='utf-8');api=(be/'app/api/v1/api.py').read_text(encoding='utf-8')
    checks=[
      ('Main Screen Computer Vision launcher',"label: 'Computer Vision'" in main and "navigate('/computer-vision')" in main),
      ('Computer Vision frontend route','/computer-vision' in app and 'ComputerVisionPage' in app),
      ('Computer Vision backend router','vision_app_api' in api and 'prefix="/computer-vision"' in api),
      ('IOT Modbus controller',(be/'app/services/vision_app/io_runtime.py').exists() and 'pulse_result' in (be/'app/services/vision_app/io_runtime.py').read_text()),
      ('Master Sample ROI search methods',all(x in (be/'app/services/vision_app/roi_search.py').read_text() for x in ['locate_manual','locate_blur_template','locate_fourier','phaseCorrelate'])),
      ('Vision Program Global/Local runtime','global_services' in (be/'app/services/vision_app/runtime.py').read_text() and 'station_services' in (be/'app/services/vision_app/runtime.py').read_text()),
      ('Frontend IOT/Master/Working modules',all((fe/p).exists() for p in ['src/components/ComputerVision/IotModulePanel.tsx','src/components/ComputerVision/MasterSamplePanel.tsx','src/components/ComputerVision/WorkingModulePanel.tsx'])),
      ('Master ROI drawing viewport','onDraw' in (fe/'src/components/ComputerVision/VisionViewport.tsx').read_text()),
      ('Context generator Computer Vision domain','Computer Vision Program' in (fe/'tools/generate_llm_context_map.py').read_text()),
      ('v0.7 handoff MD',(fe/'docs/llm_context/updates/v0700_computer_vision_frame.md').exists()),
    ]
    for label,ok in checks:print(f'[{"OK" if ok else "FAIL"}] {label}');fails += 0 if ok else 1
    count,pf=python_syntax(be)
    if pf:
        print('[FAIL] Python syntax');[print('  -',x) for x in pf];fails+=len(pf)
    else:print(f'[OK] Python syntax ({count} new backend files)')
    if importlib.util.find_spec('pytest') is not None:
        r=subprocess.run([sys.executable,'-m','pytest','-q','tests/vision_app/test_vision_app_frame_v0100.py'],cwd=str(be),text=True,capture_output=True)
        if r.returncode==0:print('[OK] Vision App backend tests');print(r.stdout.strip())
        else:print('[FAIL] Vision App backend tests');print((r.stdout+'\n'+r.stderr).strip());fails+=1
    else:print('[SKIP] pytest unavailable')
    ts=ts_transpile(fe);txt=(ts.stdout+'\n'+ts.stderr).strip()
    if ts.returncode==0:print('[OK] TypeScript syntax/transpile')
    elif 'Cannot find module' in txt or 'MODULE_NOT_FOUND' in txt:print('[SKIP] TypeScript module unavailable')
    else:print('[FAIL] TypeScript syntax/transpile');print(txt);fails+=1
    if not skip_build and (fe/'package.json').exists() and (fe/'node_modules').exists():
        r=subprocess.run(['npm','run','build'],cwd=str(fe));print('[OK] Frontend npm build' if r.returncode==0 else '[FAIL] Frontend npm build');fails += 0 if r.returncode==0 else 1
    else:print('[SKIP] Frontend npm build')
    try:
        regenerate(fe,be);arch=fe/'docs/llm_context/SYSTEM_ARCHITECTURE.md';bund=fe/'docs/llm_context/SYSTEM_CONTEXT_BUNDLES.md';ok=arch.exists() and bund.exists() and 'Computer Vision Program' in arch.read_text(encoding='utf-8') and 'Computer Vision Program' in bund.read_text(encoding='utf-8');print(f'[{"OK" if ok else "FAIL"}] Regenerated Computer Vision architecture/context bundle');fails += 0 if ok else 1
    except Exception as e:print('[FAIL] Context regeneration:',e);fails+=1
    if fails:print(f'[FAIL] v0.7.0 verification finished with {fails} issue(s).');return 1
    print('[OK] Computer Vision frame v0.7.0 verified.');return 0


def main():
    p=argparse.ArgumentParser();p.add_argument('command',choices=['scan','apply','verify']);p.add_argument('--frontend');p.add_argument('--backend');p.add_argument('--skip-build',action='store_true');a=p.parse_args()
    try:
        fe,be=resolve_roots(a.frontend,a.backend)
        if a.command=='scan':return scan(fe,be)
        if a.command=='apply':return apply(fe,be)
        return verify(fe,be,a.skip_build)
    except Exception as e:print('[ERROR]',e);return 2
if __name__=='__main__':raise SystemExit(main())
